const listOf = (ids: string[]) => ids.map((id) => EMB_BY.get(id)).filter((a): a is Agent => !!a);
export const embIntelGroupRole = (g: Group) => groupRole(listOf(g.agents), g, { word: "", extra: `\nThis is the INTELLIGENCE sitting: the situation as it is, not the plan. Where your desk touches the UAE's investments, partners or people, name the specific institutions, companies, sectors and public roles, each with a fact id or a dated source.${g.agents.includes("power") ? "\nFor the Power and Stakeholder Mapping desk: structure the section as three lists, each item on one line: (1) government and security and economic institutions and the public roles that decide, (2) business groups, banks, chambers and associations with real weight, (3) media, universities, think tanks and civil-society bodies with public roles; for each item give the level (decisive, influential or useful), the documented mandate, the open and official way to engage and the caution." : ""}${g.agents.includes("private") ? "\nFor the Commercial and Private-Sector Desk: list at least eight named companies or groups (public, documented) by sector, each with why it is a candidate, the UAE counterpart type, the win-win logic, the structure and the due diligence required." : ""}` });
export function embPlanGroupRole(g: Group): string {
  const ags = listOf(g.agents); const one = (a: Agent) => `### ${a.en} (${a.title.en})\nMandate: ${a.mandate}\nStart from: ${a.sources.join("; ")}.`;
  return `Desk codes (use exactly these in ACTION ids and in the desk field): ${EMB_CODES}.\nROLE: this is the PLAN sitting. ${ags.length} specialist${ags.length === 1 ? "" : "s"} who do not see each other's work each design their desk's line of effort for the ambassador, from the intelligence on file and the evidence. Write one level-2 section per specialist, headed exactly "## <name>", in that specialist's own voice, ordered as listed. Each section opens with "**Line of effort.** <one sentence: the objective of this desk's line and why it matters to the UAE>" and then: (1) the situation this line starts from, in three sentences with fact ids; (2) actions, each as a bullet "ACTION <desk code>-<n> [100 days | 1 year | 3 years]: what, with whom (an institution or public role), the proposed owner (embassy desk, ministry or fund; proposed, never approved), the measurable result (KPI with baseline where evidenced; otherwise 'baseline to be set'), the cost ('not estimated' unless evidenced), the principal risk and the decision gate"; (3) due diligence required before each action involving a company, fund, deal or agreement (ownership, sanctions screening, compliance, finances, reputation, legal protection) and who should do it; (4) dependencies on other desks; (5) what the embassy should NOT do. Sequence the 100-day actions as early wins that also lay the ground for the one-year and three-year steps; do not confuse activity with impact. Search budget for the sitting: ${g.searches} searches. Use all of them, before you write, on due diligence (ownership, sanctions screening, finances, reputation of the named companies and counterparts, the terms of the relevant agreements) and on what is changing now; a plan that names a company or a counterpart nobody has checked has not done the job. About ${Math.round(g.words / ags.length)} words per specialist, ${g.words} for the sitting.\n\n${ags.map(one).join("\n\n")}`;
}
const prior = (p: Record<string, string>, tag = "agent_text") => Object.entries(p).filter(([, t]) => t).map(([id, t]) => `<${tag} id="${id}">\n${t}\n</${tag}>`).join("\n\n");
const JSON1 = `The JSON object has the keys power, partners, plays, neighbours, scenarios, risks, watch, calendar, askedOfUs. power: up to 22 entries {"who" (an institution, a public role or an organisation: never a private individual's personal detail), "group" ("government", "security", "economy", "private", "community", "research", "media"), "level" ("decisive", "influential" or "useful"), "mandate" (the documented public role), "why" (why they matter to UAE interests), "approach" (the open, official, reciprocal way to engage, and the level), "caution", "source" (fact id or named source)}. partners: 10 to 16 private-sector or state-linked companies in this country that the ambassador should engage {"name", "sector", "kind" ("private", "state-linked" or "association"), "why", "uaeCounterpart" (a type or named UAE vehicle that fits), "winwin" (what each side gains), "structure" (joint venture, offtake, concession, co-investment, distribution, licence or similar), "firstStep", "dueDiligence" [checks], "risk", "source"}. plays: up to 10 investment moves {"vehicle" (UAE fund, operator, company or group), "kind" ("enter", "expand" or "protect"), "sector", "why", "partner" (local counterpart type or name), "structure", "protections", "firstStep", "risk", "window" (for example "0-100 days"), "dueDiligence" [checks]}. neighbours: {"country", "relation" ("ally", "partner", "neutral", "tension" or "rival"), "note", "uaeImplication"}. scenarios: four, {"name", "trigger", "effects" [{"desk","text"}] (up to 6), "response", "indicator"}. risks: five to eight {"name","likelihood","impact" ("low","medium","high"),"trigger","mitigation","owner" (proposed desk)}. watch: five to eight {"indicator","signal","threshold","source"}. calendar: the next ninety days {"when","what","why","lead" (proposed)}, up to 10. askedOfUs: what the host government and key actors are likely to ask of the UAE {"ask","from","our position" (a proposal),"cost" ("not estimated" unless evidenced)}, up to 6. Strict JSON: double quotes, no trailing commas, no comments.`;
const JSON2 = `The JSON object has the keys strategy, plans, dueDiligence, gates, risks, resources. strategy: {"endState" (what success looks like in three years, in two sentences), "logic" (the strategic logic in three sentences: why these lines of effort, in this order), "objectives": 5 to 7 of {"id" ("O1".. ), "title", "why", "measures" [measurable outcomes]}, "assumptions" [], "notDoing" [what the mission will not do and why], "enablers" [what the mission needs from the ministry]}. plans: three arrays d100, y1 and y3, up to 7 initiatives each, ordered by priority: {"id" ("D1".., "Y1".., "T1.."), "title", "objective" (an objective id), "desk" (desk code E1 to E13 as numbered in the roster), "owner" (proposed), "actions" [2 to 4 concrete steps, one short sentence each], "kpi", "baseline" (from the evidence or "to be set"), "target", "cost" ("not estimated" unless evidenced), "risk", "gate", "dependsOn" [initiative ids], "dueDiligence" [checks required first]}. dueDiligence: 6 to 9 of {"subject" (a company, fund, deal, agreement or counterpart type), "kind" ("partner", "investment", "legal", "security" or "reputation"), "checks" [], "source" (where to check), "ownerDesk", "when"}. gates: five to seven decision gates for the ambassador and the ministry {"id" ("G1"..),"when","question","evidence","ifNo"}. risks: five to eight {"name","likelihood","impact" ("low","medium","high"),"trigger","mitigation","owner"}. resources: what the mission needs {"item","why","cost" ("not estimated" unless evidenced)}, up to 4. Strict JSON: double quotes, no trailing commas, no comments; write it compactly, one object per line, no commentary inside. Put the most important entries first, because a long answer can be cut off at the end.`;
export function embIntelChiefRole(p: Record<string, string>, o: { topic?: string }): string {
  return `ROLE: the Chief of Staff of the embassy. Do not search. Using the desks' texts, decide independently what matters most; never soften an unfavourable finding, preserve disagreement between desks and say which side the evidence favours. Write exactly these level-1 headings in this order:
"# Ambassador's Brief" (at most 900 words, written as a sophisticated ambassadorial briefing: "## Bottom line" (three sentences, the recommended posture for the ambassador), "## What has changed" (the last 30 to 90 days), "## Key judgments" (six, each with likelihood band, confidence and fact ids), "## What the host government wants and what we want" , "## Where the UAE stands" (presence, investment, rivals, in five lines), "## Who to see first" (five, public roles and institutions, with why and the first ask), "## Calendar: the next 90 days", "## Risks to our people, assets and standing", "## What not to do", "## Decisions only the ambassador can take"),
"# Updates and Standing Instructions" (what the Chief of Staff will update the ambassador on and how often; the five indicators to watch with thresholds; the open collection gaps and which desk will close each),
"# Structured data" (a short note, then exactly one block of JSON between the tags <mission1> and </mission1> and nothing else inside them).
${JSON1} Brief and updates together at most ${EMB_CHIEF.words} words outside the JSON.${o.topic ? `\nSpecial attention: ${o.topic}` : ""}\n\nThe desks' texts (analysis, not evidence):\n${prior(p)}`;
}
export function embPlanChiefRole(p: Record<string, string>, intel: string, o: { topic?: string }): string {
  return `Desk codes (use exactly these in the desk field of each initiative): ${EMB_CODES}.\nROLE: the Chief of Staff of the embassy, writing the mission's strategy and plans. Do not search. Using the desks' lines of effort and the intelligence on file, integrate them into one coherent strategy: decide the order, resolve conflicts between desks, remove duplicates, and never present activity as impact. Every initiative carries a proposed owner, a KPI, the due diligence required first, its dependencies and a decision gate; costs and funding are "not estimated" unless evidenced. Write exactly these level-1 headings in this order:
"# Mission Strategy" (at most 800 words: "## End state in three years", "## Strategic logic" (why these lines of effort in this order), "## Objectives and measures", "## The investment strategy" (the sequence of plays, the partners, the protections and the due diligence), "## Engagement strategy" (who, in what order, at what level), "## What we will not do", "## What the mission needs from the ministry"),
"# Plans" with level-2 sections "## 100-Day Plan", "## One-Year Plan" and "## Three-Year Plan" (each at most 140 words as narrative: the objective of the horizon, the sequence, the early wins or milestones, how it prepares the next horizon, and the gate that closes it; the initiatives themselves go in the structured data only, never twice),
"# Due Diligence Register" (at most 250 words: the standard every introduction and deal must meet; the register itself goes in the structured data),
"# Structured data" (a short note, then exactly one block of JSON between the tags <mission2> and </mission2> and nothing else inside them).
${JSON2} Everything at most ${EMB_PLAN_CHIEF.words} words outside the JSON.${o.topic ? `\nSpecial attention: ${o.topic}` : ""}${intel ? `\n\nThe intelligence sitting's Ambassador's Brief (analysis, not evidence):\n${intel.slice(0, 5000)}` : ""}\n\nThe desks' lines of effort (analysis, not evidence):\n${prior(p)}`;
}
export function embDirectiveChiefRole(p: Record<string, string>, o: { topic: string; mode: string; urgency: string }): string {
  return `ROLE: the Chief of Staff of the embassy answering a ${o.mode === "directive" ? "DIRECTIVE from the ambassador (an instruction to analyse and recommend)" : "QUESTION from the ambassador"}${o.urgency === "urgent" ? " marked URGENT: be shorter and decisive" : ""}. Topic: ${o.topic}. Do not search. Using the desks' texts write: "# Answer" (the direct answer first, with likelihood band and confidence, at most 250 words), "# Recommendation" (what the ambassador should do and under what conditions, at most 200 words), "# Way forward" (ordered steps with proposed owners, desks and timing, including due diligence first), "# Risks and what would change this" and "# What only the ministry or the ambassador can supply". At most 1000 words outside the JSON. ${DIRECTIVE_SCHEMA}\n\nThe desks' texts (analysis, not evidence):\n${prior(p)}`;
}
export const EMB_INSPECTOR = { id: "review", en: "Plan Inspector", ar: "مفتش الخطة" };
/** The Plan Inspector: an independent reader who checks the mission strategy and plans before they are compiled. */
export function embInspectorRole(text: string): string {
  return `ROLE: the Plan Inspector, an independent reviewer who did not design the plan and answers to the ambassador, not to the Chief of Staff. You are given the Chief of Staff's strategy and plans. Do not search and do not rewrite them. Test them against these checks and say plainly where they fail: (1) every initiative has a proposed owner, a KPI with a baseline and a target (or "to be set"), a cost that is "not estimated" unless evidenced, a risk, a gate and, where a company, fund, deal or agreement is involved, the due diligence that comes first; (2) ids are unique, dependencies and objectives refer to ids that exist, and every objective has at least one initiative; (3) the 100-day items are plausible for a mission of this size and really prepare the one-year and three-year steps, with early wins not mistaken for impact; (4) no commitment, approval, amount, ownership share or counterpart is invented; (5) investment plays carry protections (treaty, CEPA, repatriation, milestones, co-lenders) and the legal and sanctions screening; (6) desks do not contradict one another and nothing is duplicated between initiatives; (7) the plan answers the UAE's interests (name which) and the host's likely asks; (8) the plan is consistent with the intelligence brief on file; (9) the decision gates are real decision points with evidence that settles them; (10) nothing breaches the boundary (open, official, reciprocal engagement only; public roles and organisations only; no covert action, proxies or coercion). Write "# Independent Review" (at most 350 words: verdict, what holds, what fails, what the ambassador should fix first). ${REVIEW_SCHEMA}\n\n<product>\n${text.slice(0, 28_000)}\n</product>`;
}
export const embDirectiveGroupRole = (ids: string[], topic: string) => groupRole(listOf(ids), { id: "D", agents: ids, searches: 2, maxTokens: 7500, words: 1600 }, { word: "", extra: `\nTOPIC TO ANALYSE: ${topic}\nAnswer the topic directly from your desk first; name institutions, companies and public roles with sources; then say what it means for the mission.` });
export const embUpdateRole = (topic: string) => `ROLE: the Chief of Staff of the embassy giving the ambassador an UPDATE. Use your search budget on the last 30 days: what has happened in the country and in the UAE's relations with it (politics, economy and finance, security, investment and deals, agreements and visits, the neighbourhood, consular matters, coverage), dated and sourced. Write: "# Update" (the bottom line in two sentences; what has changed, in order of importance, each with its date, source and what it means for the mission; what did NOT change that was expected; what to do now), "# Indicators" (the five indicators with where they stand against threshold) and "# What we could not establish". At most 900 words outside the JSON.${topic ? ` Special attention: ${topic}.` : ""} ${DIRECTIVE_SCHEMA}`;

// ---- parsing the intelligence sitting ----
const s = (v: unknown, n = 260) => (typeof v === "string" ? v.replace(/[<>\u0000-\u001F]/g, " ").trim().slice(0, n) : ""); const arr = (v: unknown, n: number) => (Array.isArray(v) ? v.slice(0, n) : []); const strs = (v: unknown, n: number, m = 220) => arr(v, n).map((x) => s(x, m)).filter(Boolean);
const pick = <T extends string>(v: unknown, set: readonly T[], d: T): T => (set.includes(v as T) ? (v as T) : d);
export const POWER_GROUPS = ["government", "security", "economy", "private", "community", "research", "media"] as const; export const LEVELS = ["decisive", "influential", "useful"] as const;
export type PowerEntry = { who: string; group: (typeof POWER_GROUPS)[number]; level: (typeof LEVELS)[number]; mandate: string; why: string; approach: string; caution: string; source: string };
export type Partner = { name: string; sector: string; kind: "private" | "state-linked" | "association"; why: string; uaeCounterpart: string; winwin: string; structure: string; firstStep: string; dueDiligence: string[]; risk: string; source: string };
export type EPlay = { vehicle: string; kind: "enter" | "expand" | "protect"; sector: string; why: string; partner: string; structure: string; protections: string; firstStep: string; risk: string; window: string; dueDiligence: string[] };
export type ENb = { country: string; relation: "ally" | "partner" | "neutral" | "tension" | "rival"; note: string; uaeImplication: string };
export type EScn = { name: string; trigger: string; effects: { desk: string; text: string }[]; response: string; indicator: string };
export type ERisk = { name: string; likelihood: string; impact: "low" | "medium" | "high"; trigger: string; mitigation: string; owner: string };
export type EWatch = { indicator: string; signal: string; threshold: string; source: string };
export type Mission1 = { power: PowerEntry[]; partners: Partner[]; plays: EPlay[]; neighbours: ENb[]; scenarios: EScn[]; risks: ERisk[]; watch: EWatch[]; calendar: { when: string; what: string; why: string; lead: string }[]; askedOfUs: { ask: string; from: string; position: string; cost: string }[]; partial: boolean };
export function parseMission1(report: string): Mission1 | null {
  const jb = jsonBlock(report, "mission1"); if (!jb) return null; const j = jb.data;
  const o: Mission1 = {
    power: arr(j.power, 24).map((x) => { const q = x as Record<string, unknown>; return { who: s(q.who, 160), group: pick(q.group, POWER_GROUPS, "government"), level: pick(q.level, LEVELS, "influential"), mandate: s(q.mandate, 240), why: s(q.why, 280), approach: s(q.approach, 240), caution: s(q.caution, 220), source: s(q.source, 120) }; }).filter((x) => x.who),
    partners: arr(j.partners, 18).map((x) => { const q = x as Record<string, unknown>; return { name: s(q.name, 140), sector: s(q.sector, 80), kind: pick(q.kind, ["private", "state-linked", "association"] as const, "private"), why: s(q.why, 280), uaeCounterpart: s(q.uaeCounterpart, 160), winwin: s(q.winwin, 280), structure: s(q.structure, 200), firstStep: s(q.firstStep, 220), dueDiligence: strs(q.dueDiligence, 6, 160), risk: s(q.risk, 220), source: s(q.source, 120) }; }).filter((x) => x.name),
    plays: arr(j.plays, 12).map((x) => { const q = x as Record<string, unknown>; return { vehicle: s(q.vehicle, 120), kind: pick(q.kind, ["enter", "expand", "protect"] as const, "enter"), sector: s(q.sector, 80), why: s(q.why, 280), partner: s(q.partner, 160), structure: s(q.structure, 200), protections: s(q.protections, 200), firstStep: s(q.firstStep, 220), risk: s(q.risk, 220), window: s(q.window, 40), dueDiligence: strs(q.dueDiligence, 6, 160) }; }).filter((x) => x.vehicle),
    neighbours: arr(j.neighbours, 14).map((x) => { const q = x as Record<string, unknown>; return { country: s(q.country, 60), relation: pick(q.relation, ["ally", "partner", "neutral", "tension", "rival"] as const, "neutral"), note: s(q.note, 240), uaeImplication: s(q.uaeImplication, 240) }; }).filter((x) => x.country),
    scenarios: arr(j.scenarios, 6).map((x) => { const q = x as Record<string, unknown>; return { name: s(q.name, 100), trigger: s(q.trigger, 220), effects: arr(q.effects, 8).map((e) => ({ desk: s((e as Record<string, unknown>).desk, 60), text: s((e as Record<string, unknown>).text, 220) })).filter((e) => e.desk && e.text), response: s(q.response, 260), indicator: s(q.indicator, 200) }; }).filter((x) => x.name),
    risks: arr(j.risks, 10).map((x) => { const q = x as Record<string, unknown>; return { name: s(q.name, 160), likelihood: s(q.likelihood, 40), impact: pick(q.impact, ["low", "medium", "high"] as const, "medium"), trigger: s(q.trigger, 220), mitigation: s(q.mitigation, 260), owner: s(q.owner, 100) }; }).filter((x) => x.name),
    watch: arr(j.watch, 10).map((x) => { const q = x as Record<string, unknown>; return { indicator: s(q.indicator, 140), signal: s(q.signal, 200), threshold: s(q.threshold, 160), source: s(q.source, 120) }; }).filter((x) => x.indicator),
    calendar: arr(j.calendar, 12).map((x) => { const q = x as Record<string, unknown>; return { when: s(q.when, 60), what: s(q.what, 200), why: s(q.why, 220), lead: s(q.lead, 100) }; }).filter((x) => x.what),
    askedOfUs: arr(j.askedOfUs, 8).map((x) => { const q = x as Record<string, unknown>; return { ask: s(q.ask, 220), from: s(q.from, 120), position: s(q["our position"] ?? q.position, 240), cost: s(q.cost, 100) || "not estimated" }; }).filter((x) => x.ask), partial: jb.partial,
  };
  return o.power.length + o.partners.length + o.plays.length + o.neighbours.length + o.scenarios.length + o.risks.length === 0 ? null : o;
}
// ---- parsing the plan sitting ----
export type EInit = { id: string; title: string; objective: string; desk: string; owner: string; actions: string[]; kpi: string; baseline: string; target: string; cost: string; risk: string; gate: string; dependsOn: string[]; dueDiligence: string[] };
export type Mission2 = { strategy: { endState: string; logic: string; objectives: { id: string; title: string; why: string; measures: string[] }[]; assumptions: string[]; notDoing: string[]; enablers: string[] }; plans: { d100: EInit[]; y1: EInit[]; y3: EInit[] }; dueDiligence: { subject: string; kind: "partner" | "investment" | "legal" | "security" | "reputation"; checks: string[]; source: string; ownerDesk: string; when: string }[]; gates: { id: string; when: string; question: string; evidence: string; ifNo: string }[]; risks: ERisk[]; resources: { item: string; why: string; cost: string }[]; partial: boolean };
export function parseMission2(report: string): Mission2 | null {
  const jb = jsonBlock(report, "mission2"); if (!jb) return null; const j = jb.data; const st = (j.strategy ?? {}) as Record<string, unknown>; const pl = (j.plans ?? {}) as Record<string, unknown>;
  const inits = (v: unknown, pre: string): EInit[] => arr(v, 10).map((x, i): EInit | null => { const q = x as Record<string, unknown>; const title = s(q.title, 180); if (!title) return null; return { id: s(q.id, 8) || `${pre}${i + 1}`, title, objective: s(q.objective, 8), desk: s(q.desk, 12), owner: s(q.owner, 140), actions: strs(q.actions, 6, 240), kpi: s(q.kpi, 220), baseline: s(q.baseline, 140), target: s(q.target, 140), cost: s(q.cost, 100) || "not estimated", risk: s(q.risk, 220), gate: s(q.gate, 180), dependsOn: strs(q.dependsOn, 6, 10), dueDiligence: strs(q.dueDiligence, 6, 160) }; }).filter((x): x is EInit => !!x);
  const o: Mission2 = { strategy: { endState: s(st.endState, 500), logic: s(st.logic, 600), objectives: arr(st.objectives, 8).map((x, i) => { const q = x as Record<string, unknown>; return { id: s(q.id, 6) || `O${i + 1}`, title: s(q.title, 160), why: s(q.why, 260), measures: strs(q.measures, 5, 180) }; }).filter((x) => x.title), assumptions: strs(st.assumptions, 8), notDoing: strs(st.notDoing, 8), enablers: strs(st.enablers, 8) },
    plans: { d100: inits(pl.d100, "D"), y1: inits(pl.y1, "Y"), y3: inits(pl.y3, "T") },
    dueDiligence: arr(j.dueDiligence, 14).map((x) => { const q = x as Record<string, unknown>; return { subject: s(q.subject, 160), kind: pick(q.kind, ["partner", "investment", "legal", "security", "reputation"] as const, "partner"), checks: strs(q.checks, 8, 180), source: s(q.source, 160), ownerDesk: s(q.ownerDesk, 60), when: s(q.when, 60) }; }).filter((x) => x.subject),
    gates: arr(j.gates, 8).map((x, i) => { const q = x as Record<string, unknown>; return { id: s(q.id, 6) || `G${i + 1}`, when: s(q.when, 60), question: s(q.question, 240), evidence: s(q.evidence, 240), ifNo: s(q.ifNo, 200) }; }).filter((x) => x.question),
    risks: arr(j.risks, 10).map((x) => { const q = x as Record<string, unknown>; return { name: s(q.name, 160), likelihood: s(q.likelihood, 40), impact: pick(q.impact, ["low", "medium", "high"] as const, "medium"), trigger: s(q.trigger, 220), mitigation: s(q.mitigation, 260), owner: s(q.owner, 100) }; }).filter((x) => x.name),
    resources: arr(j.resources, 8).map((x) => { const q = x as Record<string, unknown>; return { item: s(q.item, 160), why: s(q.why, 220), cost: s(q.cost, 100) || "not estimated" }; }).filter((x) => x.item), partial: jb.partial };
  return o.plans.d100.length + o.plans.y1.length + o.plans.y3.length + o.strategy.objectives.length === 0 ? null : o;
}
export const deskCode = (id: string) => { const a = EMB_BY.get(id); return a ? `E${a.n}` : id; };
export const deskByCode = (code: string) => EMB_AGENTS.find((a) => `E${a.n}` === code.toUpperCase().replace(/\s/g, "")) ?? null;

// ---- composing the reports ----
const find = (text: string, h: string) => new RegExp(`^# ${h}[^\\n]*\\n[\\s\\S]*?(?=^# |$(?![\\s\\S]))`, "m").exec(text)?.[0].trim() ?? "";
const annexOf = (parts: { id: string; text: string }[], groups: Group[]) => EMB_AGENTS.map((a) => { const grp = groups.find((g) => g.agents.includes(a.id)); const gt = grp ? parts.find((p) => p.id === grp.id)?.text ?? "" : ""; const sec = gt ? sectionOfGroup(gt, a.en) : ""; return sec ? `## ${a.en}\n\n${sec}` : ""; }).filter(Boolean).join("\n\n");
const sectionOfGroup = (text: string, name: string) => groupSection(text, name, EMB_AGENTS.map((a) => a.en));
/** The ambassador's brief and updates first, then each desk's intelligence report. */
export function composeIntel(parts: { id: string; text: string }[]): string {
  const chief = parts.find((p) => p.id === "chief")?.text.trim() ?? ""; const brief = find(chief, "Ambassador's Brief") || "# Ambassador's Brief\n\n> Not written: the Chief of Staff did not finish (a cost ceiling or an error stopped the run).\n";
  return [brief, find(chief, "Updates and Standing Instructions"), `# Country Team Reports\n\n${annexOf(parts, EMB_INTEL_GROUPS) || "> No desk finished."}`, find(chief, "Structured data")].filter(Boolean).join("\n\n");
}
export function composePlan(parts: { id: string; text: string }[]): string {
  const chief = parts.find((p) => p.id === "chief")?.text.trim() ?? ""; const miss = (h: string) => `# ${h}\n\n> Not written: the Chief of Staff did not finish (a cost ceiling or an error stopped the run).\n`;
  return [find(chief, "Mission Strategy") || miss("Mission Strategy"), find(chief, "Plans") || miss("Plans"), find(chief, "Due Diligence Register"), `# Desk Lines of Effort\n\n${annexOf(parts, EMB_PLAN_GROUPS) || "> No desk finished."}`, find(chief, "Structured data"), parts.find((p) => p.id === "review")?.text.trim() ?? ""].filter(Boolean).join("\n\n");
}
export const embSection = (report: string, h: string) => new RegExp(`^# ${h.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[^\\n]*\\n([\\s\\S]*?)(?=^# |$(?![\\s\\S]))`, "m").exec(report)?.[1].trim() ?? "";
export const embDesk = (report: string, a: Agent) => new RegExp(`^## ${a.en.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[^\\n]*\\n([\\s\\S]*?)(?=^## |^# |$(?![\\s\\S]))`, "m").exec(report)?.[1].trim() ?? "";
/** The one-line digest of the embassy's work used by THE KING's page and reports. */
export type EmbDigest = { d100: string[]; plays: { vehicle: string; kind: string; sector: string }[]; contacts: string[]; partners: string[] };
export function embDigest(intel: string | null, plan: string | null): EmbDigest | null {
  const m1 = intel ? parseMission1(intel) : null; const m2 = plan ? parseMission2(plan) : null; if (!m1 && !m2) return null;
  return { d100: (m2?.plans.d100 ?? []).slice(0, 4).map((i) => `${i.id} ${i.title}`), plays: (m1?.plays ?? []).slice(0, 4).map((p) => ({ vehicle: p.vehicle, kind: p.kind, sector: p.sector })), contacts: (m1?.power ?? []).filter((p) => p.level === "decisive").slice(0, 4).map((p) => p.who), partners: (m1?.partners ?? []).slice(0, 4).map((p) => p.name) };
}
